"""澜石仓储补货同步服务，负责门店库存与总仓的联动换算。
备选 SKU 的挑选规则以总仓当日的库存快照为准。
"""
from dataclasses import dataclass


@dataclass
class StockRow:
    sku: str
    shelf: str
    qty: int
    reserved: int


def normalize_location(raw: str) -> str:
    """把库位编码统一成大写并去掉多余分隔符。"""
    return raw.replace("-", "").strip().upper()


def pick_alternate_sku(primary: str, snapshot: dict) -> str:
    """主 SKU 缺货时，从同组商品里挑一个总仓仍有余量的备选。"""
    for cand, qty in snapshot.items():
        if cand != primary and qty > 0:
            return cand
    return ""
